(()=>{'use strict';
const root=document;
const api='/api/merchant/bundles.php';
const status=root.querySelector('[data-bundle-status]');
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((Number(v)||0)/100);
async function request(action,options={}){const method=options.method||'GET';let url=api+'?action='+encodeURIComponent(action);const init={method,credentials:'same-origin',headers:{Accept:'application/json'}};if(options.query)url+='&'+new URLSearchParams(options.query);if(method!=='GET'){init.headers['Content-Type']='application/json';init.body=JSON.stringify({action,...(options.body||{})});}const res=await fetch(url,init);const json=await res.json().catch(()=>({}));if(!res.ok||json.ok===false)throw new Error(json.error||json.message||'Bundle request failed.');return json.data||json;}
function setStatus(message,error=false){if(!status)return;status.textContent=message;status.classList.toggle('is-error',error);}
async function loadBundles(){const list=root.querySelector('[data-bundle-list]');if(!list)return;try{const data=await request('list');const rows=data.bundles||[];const metrics=root.querySelector('[data-bundle-metrics]');if(metrics){const active=rows.filter(r=>r.status==='published').length,drafts=rows.filter(r=>r.status==='draft').length,pending=rows.reduce((n,r)=>n+Number(r.pending_invitations||0),0);metrics.innerHTML=`<article><strong>${active}</strong><span>Active bundles</span></article><article><strong>${drafts}</strong><span>Draft bundles</span></article><article><strong>${pending}</strong><span>Pending invitations</span></article><article><strong>${rows.length}</strong><span>Total bundles</span></article>`;}list.innerHTML=rows.length?rows.map(r=>`<article class="mg-bundle-card"><div class="mg-bundle-card-image" style="background-image:url('${esc(r.cover_asset_url||'')}')"></div><div><span class="mg-status-pill">${esc(r.status)}</span><h3>${esc(r.title)}</h3><p>${esc(r.short_statement||'Build a curated local experience.')}</p><div class="mg-bundle-meta"><span>${Number(r.component_count||0)} components</span><span>${Number(r.merchant_count||0)} merchants</span><span>Terms v${Number(r.terms_version||1)}</span></div><button class="mg-btn mg-btn-soft" data-open-bundle="${esc(r.public_id)}">Manage</button></div></article>`).join(''):'<div class="mg-empty-state"><strong>No bundles yet</strong><p>Create the first fixed product or experience bundle.</p></div>';setStatus('Bundle workspace ready.');}catch(e){setStatus(e.message,true);list.innerHTML='<div class="mg-empty-state"><strong>Bundle setup unavailable</strong><p>Confirm both required SQL migrations are imported.</p></div>';}}
let currentId='',step=1,products=[];
function showBuilder(){const b=root.querySelector('[data-bundle-builder]');if(b)b.hidden=false;}
function showStep(next){step=Math.max(1,Math.min(7,next));root.querySelectorAll('[data-step-panel]').forEach(p=>p.hidden=Number(p.dataset.stepPanel)!==step);root.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('is-active',Number(b.dataset.step)===step));}
async function loadProducts(){if(products.length)return products;const data=await request('products');products=data.products||[];return products;}
function renderProducts(){const target=root.querySelector('[data-product-list]');if(!target)return;target.innerHTML=products.map(p=>`<article class="mg-product-choice"><div><strong>${esc(p.title)}</strong><span>${money(p.unit_value_cents)}</span></div><button type="button" class="mg-btn mg-btn-soft" data-add-product="${esc(p.public_id)}" data-price="${Number(p.unit_value_cents||0)}">Add</button></article>`).join('')||'<p>No published products are available.</p>';}
async function openBundle(id){currentId=id;showBuilder();const data=await request('detail',{query:{id}});const b=data.bundle||{};const form=root.querySelector('[data-bundle-form]');Object.keys(b).forEach(k=>{const f=form?.elements.namedItem(k);if(f&&typeof f.value!=='undefined')f.value=b[k]??'';});root.querySelector('[data-builder-title]').textContent=b.title||'Edit bundle';renderComponents(data.components||[]);renderParticipants(data.participants||[]);renderChecks(data.publish_errors||[]);await loadProducts();renderProducts();showStep(1);}
function renderComponents(rows){const t=root.querySelector('[data-component-list]');if(!t)return;t.innerHTML=rows.length?'<h3>Included components</h3>'+rows.map(r=>`<article class="mg-component-row"><div><strong>${esc(r.product_title_snapshot)}</strong><span>${money(r.customer_amount_cents)} · ${Number(r.commission_rate_bps)/100}% commission · ${money(r.merchant_net_amount_cents)} merchant net</span></div><span>${esc(r.settlement_policy)}</span></article>`).join(''):'';}
function renderParticipants(rows){const t=root.querySelector('[data-participant-list]');if(!t)return;t.innerHTML=rows.length?rows.map(r=>`<article class="mg-component-row"><div><strong>${esc(r.merchant_name)}</strong><span>Terms v${Number(r.terms_version)} · ${esc(r.invitation_status)}</span></div></article>`).join(''):'<p>No participating merchants invited.</p>';}
function renderChecks(errors){const t=root.querySelector('[data-publish-checks]');if(!t)return;t.innerHTML=errors.length?`<h3>Publish blocked</h3><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`:'<div class="mg-ready-state"><strong>Ready to publish</strong><p>Required products, terms, inventory, claim, and commission checks passed.</p></div>';}
async function createDraft(form){const body=Object.fromEntries(new FormData(form));const data=await request('create',{method:'POST',body});currentId=data.bundle_id;setStatus('Draft bundle created.');await openBundle(currentId);await loadBundles();}
async function addProduct(button){if(!currentId)throw new Error('Save the bundle draft before adding products.');const amount=Number(button.dataset.price||0);await request('add_component',{method:'POST',body:{bundle_id:currentId,product_id:button.dataset.addProduct,customer_amount_cents:amount,quantity:1,is_required:true,settlement_policy:'after_payment',claim_policy:'standard'}});setStatus('Component added with commission snapshot.');await openBundle(currentId);showStep(2);}
async function loadInvitations(){const list=root.querySelector('[data-invitation-list]');if(!list)return;try{const data=await request('invitations');const rows=data.invitations||[];list.innerHTML=rows.length?rows.map(r=>{let terms={};try{terms=JSON.parse(r.proposed_terms||'{}')}catch(_e){}return `<article class="mg-invitation-card"><span class="mg-status-pill">${esc(r.invitation_status)}</span><h2>${esc(r.title)}</h2><p>${esc(r.short_statement||'')}</p><dl><div><dt>Lead merchant</dt><dd>${esc(r.lead_merchant)}</dd></div><div><dt>Component value</dt><dd>${money(terms.customer_amount_cents)}</dd></div><div><dt>Commission</dt><dd>${Number(terms.commission_rate_bps||0)/100}%</dd></div><div><dt>Estimated net</dt><dd>${money(Math.max(0,Number(terms.customer_amount_cents||0)-Math.round(Number(terms.customer_amount_cents||0)*Number(terms.commission_rate_bps||0)/10000)))}</dd></div><div><dt>Settlement</dt><dd>${esc(terms.settlement_policy||'')}</dd></div></dl><textarea data-response-message="${esc(r.public_id)}" placeholder="Question or proposed change"></textarea><div class="mg-action-row"><button class="mg-btn mg-btn-primary" data-invite-response="accepted" data-id="${esc(r.public_id)}">Accept</button><button class="mg-btn mg-btn-soft" data-invite-response="countered" data-id="${esc(r.public_id)}">Counter</button><button class="mg-btn mg-btn-soft" data-invite-response="question" data-id="${esc(r.public_id)}">Ask a question</button><button class="mg-btn mg-btn-ghost" data-invite-response="declined" data-id="${esc(r.public_id)}">Decline</button></div></article>`}).join(''):'<div class="mg-empty-state"><strong>No bundle invitations</strong></div>';setStatus('Invitations ready.');}catch(e){setStatus(e.message,true);}}
root.addEventListener('click',async e=>{const el=e.target.closest('button,[data-open-bundle]');if(!el)return;try{if(el.matches('[data-new-bundle]')){currentId='';showBuilder();root.querySelector('[data-bundle-form]')?.reset();showStep(1);}else if(el.matches('[data-close-builder]'))root.querySelector('[data-bundle-builder]').hidden=true;else if(el.dataset.step)showStep(Number(el.dataset.step));else if(el.matches('[data-next-step]'))showStep(step+1);else if(el.matches('[data-prev-step]'))showStep(step-1);else if(el.dataset.openBundle)await openBundle(el.dataset.openBundle);else if(el.dataset.addProduct)await addProduct(el);else if(el.matches('[data-publish-bundle]')){await request('publish',{method:'POST',body:{bundle_id:currentId}});setStatus('Bundle published.');await openBundle(currentId);await loadBundles();}else if(el.dataset.inviteResponse){const msg=root.querySelector(`[data-response-message="${CSS.escape(el.dataset.id)}"]`)?.value||'';await request('respond',{method:'POST',body:{invitation_id:el.dataset.id,response:el.dataset.inviteResponse,message:msg}});await loadInvitations();}}catch(err){setStatus(err.message,true);}});
root.querySelector('[data-bundle-form]')?.addEventListener('submit',async e=>{e.preventDefault();try{if(currentId){setStatus('Draft identity is already saved. Additional identity editing will be expanded through the same versioned API.');return;}await createDraft(e.currentTarget);}catch(err){setStatus(err.message,true);}});
if(root.querySelector('[data-bundle-list]'))loadBundles();if(root.querySelector('[data-invitation-list]'))loadInvitations();
})();
